<?php
 class Log { const INFO = 0; const WARNING = 1; const ERROR = 2; const MESSAGE = 0; const TEXT = 1; const BEGIN = 2; const END = 3; public $name; public $onHtml; public $formatTime = "d.m.Y H:i:s"; public $formatPad = "    "; protected $html; protected $type; protected $time; protected $blocks = []; protected $pad = ""; function __construct ($name = null, $onHtml = false, $withoutSeparator = false) { $name = $name ?: getSessionValue('app'); $name = $name ?: 'common'; $this->name = getLogPath() . $name . '.log'; $this->onHtml = $onHtml; if (!$withoutSeparator) { error_log("\n" . str_repeat('-', 20), 3, $this->name); } } public function info ($msg, $html = null) { $this->type = self::INFO; $dt = date($this->formatTime); error_log("\n{$dt} INFO  > {$this->pad}{$msg}", 3, $this->name); if ($html || ($this->onHtml && $html !== false)) { $msg = is_string($html) ? $html : $msg; $this->addHtml("\n{$this->pad}{$msg}"); } $this->time = microtime(true); return $this; } public function warning ($msg, $html = null) { $this->type = self::WARNING; $dt = date($this->formatTime); error_log("\n{$dt} WARN  > {$this->pad}{$msg}", 3, $this->name); if ($html || ($this->onHtml && $html !== false)) { $msg = is_string($html) ? $html : $msg; $this->addHtml("\n{$this->pad}{$msg}"); } return $this; } public function error ($msg, $html = null) { $this->type = self::ERROR; $dt = date($this->formatTime); error_log("\n{$dt} ERROR > {$this->pad}{$msg}", 3, $this->name); if ($html || ($this->onHtml && $html !== false)) { $msg = is_string($html) ? $html : $msg; $this->addHtml("\n{$this->pad}{$msg}"); } return $this; } public function add ($msg, $html = null) { error_log(" $msg", 3, $this->name); if ($html || ($this->onHtml && $html !== false)) { $msg = is_string($html) ? $html : $msg; $this->addHtml(" $msg"); } return $this; } public function time ($msg = null, $html = null) { $s = round(microtime(true) - $this->time, 3); $s = " ({$s}s)"; error_log(($msg ? " $msg" : "") . $s, 3, $this->name); if ($html || ($this->onHtml && $html !== false)) { $msg = is_string($html) ? $html : $msg; $this->addHtml(($msg ? " $msg" : "") . $s); } return $this; } public function text ($msg, $html = null) { $pad = $this->formatPad; $msg = str_replace("\n", "\n$pad", trim($msg)); error_log("\n--------->\n{$pad}{$msg}\n<---------", 3, $this->name); if ($html || ($this->onHtml && $html !== false)) { $msg = is_string($html) ? str_replace("\n", "\n$pad", trim($html)) : $msg; $this->addHtml("\n--------->\n{$pad}{$msg}\n<---------", self::TEXT); } return $this; } public function begin ($msg = null, $html = null) { if ($msg) { $dt = date($this->formatTime); error_log("\n{$dt} BEGIN > {$this->pad}{$msg}", 3, $this->name); if ($html || ($this->onHtml && $html !== false)) { $msg = is_string($html) ? $html : $msg; $this->addHtml("\n{$this->pad}{$msg}", self::BEGIN); } } $this->blocks[] = microtime(true); $this->pad = str_repeat($this->formatPad, count($this->blocks)); $this->type = self::INFO; return $this; } public function end ($msg = null, $html = null, $time = true) { $t = array_pop($this->blocks); $this->pad = str_repeat($this->formatPad, count($this->blocks)); if ($msg || $time) { $s = ""; if ($time) { $s = round(microtime(true) - $t, 3); $s = " ({$s}s)"; } $dt = date($this->formatTime); error_log(($msg ? "\n{$dt} END   > {$this->pad}{$msg}" : "") . $s, 3, $this->name); if ($html || ($this->onHtml && $html !== false)) { $msg = is_string($html) ? $html : $msg; $this->addHtml("\n{$this->pad}{$msg}{$s}", self::END); } } $this->type = self::INFO; return $this; } public function getHtml () { return '<pre>' . str_replace("\n", "<br>", $this->html) . '</pre>'; } protected function addHtml ($value, $context = self::MESSAGE) { $style = ''; switch ($this->type) { case self::WARNING: $style = 'color:yellow'; break; case self::ERROR: $style = 'color:red'; break; } switch ($context) { case self::TEXT: $style .= ($style ? ';' : '') . 'font-style:italic'; break; case self::BEGIN: case self::END: $style = 'font-weight:bold'; break; } if (empty($this->html)) { $value = ltrim($value); } if ($style) { $value = '<span style="' . $style . '">' . $value . '</span>'; } $this->html .= $value; } }